  // ── Verificación identidad pasajero ─────────────────────────────────────────
  onPassengerVerifPhoto(slot: 'selfie' | 'front' | 'back', event: Event): void {
    const file = (event.target as HTMLInputElement).files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const url = e.target?.result as string;
      if (slot === 'selfie') { this.passengerVerifSelfie.set(file); this.passengerVerifSelfiePreview.set(url); }
      else if (slot === 'front') { this.passengerVerifFront.set(file); this.passengerVerifFrontPreview.set(url); }
      else { this.passengerVerifBack.set(file); this.passengerVerifBackPreview.set(url); }
      this.cdr.markForCheck();
    };
    reader.readAsDataURL(file);
  }

  async submitPassengerVerif(): Promise<void> {
    const selfie = this.passengerVerifSelfie();
    const front  = this.passengerVerifFront();
    const back   = this.passengerVerifBack();
    if (!selfie || !front || !back) {
      this.passengerVerifError.set('Debes tomar las 3 fotos para continuar.');
      return;
    }
    const profile = this.agProfile();
    if (!profile) return;
    this.passengerVerifSending.set(true);
    this.passengerVerifError.set(null);
    const result = await this.agService.submitPassengerVerification(profile.id, selfie, front, back);
    this.passengerVerifSending.set(false);
    if (!result.success) {
      this.passengerVerifError.set(result.error ?? 'Error al enviar. Intenta de nuevo.');
      return;
    }
    // Actualizar perfil en memoria
    this.agProfile.update(p => p ? { ...p, passenger_verified: true } : p);
    // Cerrar modal y limpiar
    this.passengerVerifModal.set(false);
    this.passengerVerifSelfie.set(null); this.passengerVerifSelfiePreview.set(null);
    this.passengerVerifFront.set(null);  this.passengerVerifFrontPreview.set(null);
    this.passengerVerifBack.set(null);   this.passengerVerifBackPreview.set(null);
    this.cdr.markForCheck();
  }

  async sendDomicilio(): Promise<void> {
    const delivery = this.domDelivery();
    if (!delivery) { this.domReqError.set('Ingresa la dirección de entrega'); return; }
    if (this.deliveryType() === 'pickup_and_deliver' && !this.domPickup()) {
      this.domReqError.set('Ingresa la dirección de recogida'); return;
    }
    if (!this._gpsRealFix && this.deliveryType() === 'from_my_location') {
      this.domReqError.set('Esperando GPS... intenta en unos segundos'); return;
    }
    const profile = this.agProfile();
    if (!profile) { this.domReqError.set('Debes iniciar sesión'); return; }
    // Verificación de identidad obligatoria desde el 2do servicio
    if ((profile.total_trips_as_passenger ?? 0) >= 1 && !profile.passenger_verified) {
      this.passengerVerifModal.set(true); return;
    }

    this.domDescription.set(this.domDescVal);
    this.domRecipientName.set(this.domRecipNameVal);
    this.domRecipientPhone.set(this.domRecipPhoneVal);

    const originLat = this.deliveryType() === 'from_my_location' ? this._currentLat : (this.domPickup()?.lat ?? this._currentLat);
    const originLng = this.deliveryType() === 'from_my_location' ? this._currentLng : (this.domPickup()?.lng ?? this._currentLng);
    const originName = this.deliveryType() === 'from_my_location'
      ? (this.currentAddress() || 'Tu ubicación actual')
      : (this.domPickup()?.name ?? 'Punto de recogida');

    this.domSending.set(true);
    this.domReqError.set(null);

    const result = await this.agService.requestTrip({
      passengerUserId: profile.id,
      passengerName: profile.full_name || undefined,
      passengerSelfieUrl: profile.selfie_url || undefined,
      originLat, originLng, originName,
      destName: delivery.name, destLat: delivery.lat, destLng: delivery.lng,
      distanceKm: this.domDistKm(),
      vehicleType: 'moto',
      offeredPrice: this.domEstPrice(),
      paymentMethod: this.tripPayment(),
      serviceType: 'domicilio',
      packageType: this.domPackageType(),
      packageDescription: this.domDescVal || undefined,
      recipientName: this.domRecipNameVal || undefined,
      recipientPhone: this.domRecipPhoneVal || undefined,
      contactlessDelivery: this.domContactless(),
    });

    this.domSending.set(false);
    if (!result.success || !result.tripId) {
      this.domReqError.set(result.error ?? 'Error al crear el domicilio. Intenta de nuevo.');
      return;
    }
    this.domActiveReqId.set(result.tripId);
    this.currentTripRequestId.set(result.tripId);
    // Sincronizar con señales del trip para que el panel aceptado y el tracker funcionen
    this.tripDest.set(delivery);
    this.tripPrice.set(this.domEstPrice());
    this.tripDistKm.set(this.domDistKm());
    this._subscribeToOffers(result.tripId);
    this._autoAssignNearestDrivers(result.tripId, originLat, originLng, 'moto', this.domEstPrice());
    this.tripSent.set(true);
    this._startWaiting();
    this.deliveryStep.set(3);
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem('movi_active_trip', JSON.stringify({
        tripId: result.tripId, status: 'searching', ts: Date.now(),
        dest: delivery, price: this.domEstPrice(), vehicle: 'moto',
      }));
    }
  }

  // ── Domicilio: driver confirms delivery code ─────────────────────────────────
  async confirmDomDeliveryCode(): Promise<void> {
    // Sync the ngModel value to the signal
    this.domCodeInput.set(this.domCodeInputValue);
    const code = this.domCodeInputValue.trim();
    if (code.length !== 4) { this.domCodeError.set('Ingresa los 4 dígitos'); return; }
    const _fstrip = this.driverFullscreenTrip();
    const reqId = _fstrip?.trip_request_id ?? _fstrip?.ag_trip_requests?.id ?? this.currentTripRequestId();
    if (!reqId) { this.domCodeError.set('No se encontró el viaje'); return; }
    this.domCodeLoading.set(true);
    const res = await this.agService.confirmDeliveryCode(reqId, code);
    this.domCodeLoading.set(false);
    if (!res.success) { this.domCodeError.set(res.error ?? 'Código incorrecto'); return; }
    this.domCodeError.set('');
    // finishDriverTrip handles receipts/rating — pass the active trip object
    const trip = this.driverFullscreenTrip();
    if (trip) {
      await this.finishDriverTrip(trip);
    }
  }

  async submitRating() {
    if (this.ratingStars() === 0) return;
    const profile = this.agProfile();
    const target  = this.ratingTarget();
    const tripId  = this.ratingTripId();
    if (!profile || !target || !tripId) { this.ratingSkipped.set(true); return; }
    this.submittingRating.set(true);
    await this.agService.submitRating(
      tripId, profile.id, target.userId, 'passenger',
      this.ratingStars(), this.ratingCommentValue,
    );
    this.submittingRating.set(false);
    this.ratingSubmitted.set(true);
    this.ratingSkipped.set(true);
  }

  skipRating() {
    this.ratingSkipped.set(true);
  }

  closeRatingModal() {
    this.ratingModal.set(false);
    this.ratingSkipped.set(false);
    this.ratingSubmitted.set(false);
    this.ratingStars.set(0);
    this.ratingCommentValue = '';
    this.ratingTarget.set(null);
    this.ratingTripId.set(null);
  }

  // Conductor: omitir calificación del pasajero y volver al home
  skipDriverRating(): void {
    this.tripReceiptModal.set(false);
    this.tripReceiptData.set(null);
    this.tripReceiptTrip.set(null);
    this._resetDriverTripState();
  }

  // Resetea el estado del conductor después de completar/calificar un viaje
  private _resetDriverTripState(): void {
    this.driverArrivalTrip.set(null);
    this._clearDriverArrivalTimer();
    if (this.driverMapFullscreen()) {
      this.driverMapFullscreen.set(false);
      this.driverFullscreenTrip.set(null);
      setTimeout(() => this._map?.resize(), 200);
    }
    if (this.navActive()) this.stopInAppNav();
    this.cdr.markForCheck();
  }

